// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _test(address user, uint256 amt1, uint256 amt2) internal {
        amt1 = bound(amt1, 0, 1000000000000000000000000000000);
        amt2 = bound(amt2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(user != address(0));
        vm.assume(amt1 > 0 && amt2 > 0);
        vm.assume(address(this).balance >= amt1 + amt2);
        try c.Deposit{value: amt1}() {} catch { return; }
        try c.Deposit{value: amt2}() {} catch { return; }
        uint expected = amt1 + amt2;
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        assertTrue(balanceAfter == expected);
    }

    function testFuzz_test(address user, uint256 amt1, uint256 amt2) public {
        _test(user, amt1, amt2);
    }

    receive() external payable {}
}
